import {all, takeEvery, takeLeading, takeLatest} from 'redux-saga/effects';
import {
    LOGIN_REQUEST,
    SERVER_REQUEST,
    UNIVERSAL_FETCH,
    SAVE_DRAFT_REQUEST
} from "../actions/common";
import login from './login';
import uModuleRequested from './uModule'
import uModuleRequestedTable from "./uModuleTable";
import uModuleRequestedCUD from "./uModuleCUD";
import {UMODULE_REQUEST, UMODULE_REQUEST_CUD, UMODULE_REQUEST_TABLE} from "../actions/uModule";

import homeRequested from "./home/serverRequestHome";
import universalFetchSaga from "./universalFetchSaga"
import saveDraft from "./saveDraft"
export default function* root() {
    yield all([
        takeLeading(UNIVERSAL_FETCH, universalFetchSaga),
        takeEvery(LOGIN_REQUEST, login),
        takeLatest(UMODULE_REQUEST, uModuleRequested),
        takeLeading(UMODULE_REQUEST_TABLE, uModuleRequestedTable),
        takeLeading(UMODULE_REQUEST_CUD, uModuleRequestedCUD),
        takeLeading(SERVER_REQUEST, homeRequested),
        takeLatest(SAVE_DRAFT_REQUEST, saveDraft)
        ]);
}


