import {includes, map, sum} from "lodash";

const recalculateTotal = (products, promotions)=>{
    let total = sum(map(products, (product)=>{
        return Math.round(product.value * product.apValue * product.amount)
    }))

    if(!promotions){
        return total
    }
    let response = 1
    if(promotions && promotions.length > 0) {
        if(promotions.length > 1) {
            response = total
            for(const promo in promotions){
                    response = Math.round(response * promotions[promo].value)
            }

        } else {
            response = sum(map(promotions, (promo) => {
                    return Math.round(promo.value * total)

            }))
        }

    } else {
        response = Math.round(total)
    }

    return response



}

const calculateTotalTobePaidPaid = (products, promotions) =>{
    if(!promotions){
        return 0
    }
    let sum = 0
    for(const promotion in promotions){
        if((includes(promotion.label, 'Tarjeta') || includes(promotion.label, 'tarjeta'))) {
            sum = sum + promotion.total
        }
    }
    return sum ? sum : 0
}

const recalculatePromotions = (products, promotions) => {
    const newTotal = recalculateTotal(products,promotions)
    if(promotions){
        if(promotions.length >= 1){
            if (promotions.length === 1) {
                for(const promo in promotions){
                    if (includes(promotions[promo].label, 'Tarjeta') || includes(promotions[promo].label, 'tarjeta')){
                        promotions[promo].total = newTotal
                    }
                }
            } else {
                for(const promo in promotions){
                    if (includes(promotions[promo].label, 'Tarjeta') || includes(promotions[promo].label, 'tarjeta')){
                        promotions[promo].total = 0
                    }
                }

            }
            return promotions

        } else {
            return []
        }
    }




}
export {calculateTotalTobePaidPaid, recalculateTotal, recalculatePromotions}


