import {SAVE_DRAFT_REQUEST, SAVE_DRAFT_SUCCESS, SAVE_DRAFT_FAILED, SAVE_DRAFT_RESET} from "../actions/common";

export default function SAVE_DRAFT(state =
                                   {success: false, loading: false,
                                       error: false,
                                   },action) {

    switch (action.type) {
        case SAVE_DRAFT_RESET:
                return {
                    loading:false, error: false, success: false
                }
        case SAVE_DRAFT_REQUEST:
            return {
                ...state, loading: true, error: false, success: false,
            };
        case SAVE_DRAFT_SUCCESS:
            return {
                ...state,  payload: action.payload, success: true, error: false, loading: false
            };
        case SAVE_DRAFT_FAILED:
            return {
                ...state, success: false,  loading: false, error: true
            }

        default:
            return state;
    }
}
