import React, {Component} from 'react';
import {connect} from "react-redux";
import {withRouter} from "react-router-dom";
import TableList from "../TableList";

class TableHandler extends Component {
    render() {
        const {prevState, handlePageCallback, header,onUpdateValues, onDeleteValues, modules, form} = this.props;
        return (

                        <TableList
                            prevState={prevState}
                            handlePageCallback={handlePageCallback}
                            header={header}
                            onUpdateValues={onUpdateValues}
                            onDeleteValues={onDeleteValues}
                            modules={modules}
                            form={form}/>
        );
    }
}

export default connect(
    (state) => ({
        table: state.UMODULE

    }),
    () => ({})
)(withRouter(TableHandler));
