import React, {Component} from 'react';
import {connect} from "react-redux";
import {withRouter} from "react-router-dom";
import {uModuleRequest} from "../../../store/actions/uModule";
import ModuleHandler from "./moduleHandler";
import Loading from "../Loading";
import {Error404} from "../index";

class ModuleParser extends Component {
    constructor(props) {
        super(props);
        this.state={
            mounted: false,
            page: '1'
        }
    }

    async componentDidMount() {
        await this.setState(async prevState => {
            const mounted = prevState.mounted
            if (!mounted) {
                const payload = {modules: this.props.modules, body: { skip: '0', compList:this.props.form}, values: {}, mode:'read' ,page: '0'}
                await this.props.readTableInformation(payload)
            }
            return {mounted: true}

        })
    }

   async handleError(){
        await this.setState(async prevState => {
            const mounted = prevState.mounted
            if (!mounted) {
                const payloads = {modules: this.props.modules, body: { skip: '0', compList:this.props.form}, values: {}, mode:'read' ,page: '0'}
                await this.props.readTableInformation({payload: payloads})
            }
            return {mounted: true}

        })


    }

    handlePage(page){
        this.setState({page: page})
    }

    render() {
        const {sending, error, success} = this.props.table
        if(sending){
            return (
                <Loading label="Cargando"/>
            )
        }
        if(error){
          return ( <Error404 handler={()=>{this.handleError()}}/>)
        }
        if(success){
            return (
                <div className="row col-12 justify-content-center align-items-start p-0 m-0">
                    <ModuleHandler page={this.state.page} pageHandlerModifier={(page)=>this.handlePage(page)}
                                   header={this.props.header} form={this.props.form} validate={this.props.validate}
                                   modules={this.props.modules}
                    />
                </div>

            );

        }

    }
}


export default connect(
    state => ({
        session: state.SESSION.session,
        table: state.UMODULE

    }),
    dispatch => ({
        readTableInformation:(payload)=> dispatch(uModuleRequest(payload))
    }))(withRouter(ModuleParser))
