import React, {Component} from "react";
import {filter, includes, map, sum} from "lodash";
import {connect} from "react-redux";
import {saveDraftRequest} from "../../../store/actions/common";
import {withRouter} from "react-router-dom";
import {calculateTotalTobePaidPaid, recalculateTotal} from "../../../store/services/calculateTotal"
import {getFromApi} from "../../../store/services/getFromApiSimple";




class PaymentChoose extends Component {
    constructor(props) {
        super(props);
        const {savedFromDraft, modules, name} = this.props;
        this.state = {
            options: [],
            values: savedFromDraft[modules][name],
            selectInput: 'default'
        }

    }
    async handleSearch(e){
        const {extra, token} =this.props;
        const source = process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY + extra[3]
        if(e.target.name === 'searchInput' && e.target.value.length > 2){ //search value must be higher than 3
            const response =await  getFromApi(source, {body:{label: e.target.value}}, token).then(
                (itm)=>{return (itm.message)},
                ()=>{return {label: "No encontrado", value: 'default'}})
            this.setState({options: response.message})
        }}
    handleSelect(e){
        this.setState({[e.target.name]: e.target.value})
    }
    handleChange(){
        const {savedFromDraft, modules, extra, name, onChangeValue} = this.props;
        if(this.state.selectInput !== 'default'){
            this.setState(
                prevState => {
                    const products = savedFromDraft[modules][extra[8]]
                    let promo = {...prevState.options[prevState.selectInput], total: 0 }
                    let promotions = [ ...prevState.values, promo]
                    let newTotal = recalculateTotal( products  , promotions)
                    let paid = calculateTotalTobePaidPaid(products, promotions)
                    const amountOfPayableMethods = sum(map(promotions, (item)=>{
                        return (includes(item.label, 'Tarjeta') || includes(item.label, 'tarjeta')) ? 1 : 0
                    }))
                    if(amountOfPayableMethods > 1){
                        promotions = map(promotions, (itm)=> {return {...itm}})
                        newTotal = recalculateTotal( products  , promotions)
                    } else {
                        if(amountOfPayableMethods !== 0){
                            for(const promo in promotions){
                                if (includes(promotions[promo].label, 'Tarjeta') || includes(promotions[promo].label, 'tarjeta')){
                                    promotions[promo].total = newTotal
                                }
                            }
                            paid = newTotal
                        }
                    }
                    onChangeValue({
                        [name]: promotions,
                        [extra[5]]: newTotal,
                        ['paid']: paid
                    })
                    return {values:  promotions}
                })
        }

    }
    handleDelete(e){
        const {savedFromDraft, modules, onChangeValue, extra, name} = this.props;
        this.setState(prevState => {
            const products = savedFromDraft[modules][extra[8]]
            let newValues = map(filter(prevState.values, (itm, ind) => {
                return ind !== e}), (item)=>{
                item.total = 0
                return item
            })
            const amountOfPayableMethods = sum(map( newValues, (item)=>{
                return (includes(item.label, 'Tarjeta') || includes(item.label, 'tarjeta')) ? 1 : 0
            }))
            let newTotal = recalculateTotal(products, newValues)
            let paid = calculateTotalTobePaidPaid(products, newValues)

            if(amountOfPayableMethods > 1){
                newValues = map( newValues, (itm)=> {return {...itm, total: 0}})
                newTotal = recalculateTotal( products  ,  newValues)
            } else {
                if(amountOfPayableMethods !== 0){
                    for(const promo in  newValues){
                        if (includes( newValues[promo].label, 'Tarjeta') || includes( newValues[promo].label, 'tarjeta')){
                            newValues[promo].total = newTotal
                        }
                    }
                    paid = newTotal
                }
            }

            onChangeValue({
                [name]: newValues,
                [extra[5]]: newTotal,
                ['paid']: paid
            })
            return {values: newValues}
            }
        )
    }
    handleTotal(e, i){
        this.setState((prevState)=> {
            const { onChangeValue, name} = this.props;
            const values = map(prevState.values, (item, ind)=>{
               return ind === i ? e.target.value : item.total
            })
            const newNormalizedValues = map(prevState.values, (item, ind)=>{
                return ind === i ? {...item, total: e.target.value} : item

            })
            const newValuesFromPaid = sum(map(values, (promo)=>{
                return promo ? parseInt(promo) : 0
            }))
            onChangeValue({
                [name]: newNormalizedValues,
                ['paid']:  newValuesFromPaid

            })
            return {values:newNormalizedValues}
        })
    }
    handleUpdateSingle(){
        const {savedFromDraft, modules, extra, name, onChangeValue} = this.props;
        const products = savedFromDraft[modules][extra[8]]
        let promotions = savedFromDraft[modules][name]
        const newTotal = recalculateTotal( products  , promotions)
        promotions[0].total = recalculateTotal( products  , promotions)
        onChangeValue({
            [name]: promotions,
            [extra[5]]: newTotal,
            ['paid']: newTotal
        })




    }

    render() {
        const {options, values} = this.state;
        const {extra, savedFromDraft, modules, name, label} = this.props;
        if(savedFromDraft[modules][name]){
            return (
                <div className={"row justify-content-center p-0 m-0 mt-2 "}>
                    <div className="row  col-12 fs-3">
                        {label}
                    </div>
                    <div className="row col-12 justify-content-between">
                        <input className={" col-sm-12 col-lg-4 text-white"} type="text" name="searchInput" onChange={(e)=>this.handleSearch(e)}/>
                        <select  className={"col-sm-12  col-lg-4 text-white"} name="selectInput" onChange={(e)=>this.handleSelect(e)}>
                            <option value={'default'}>{options.length > 0 ? 'Seleccione' : 'Buscar'}</option>
                            {options.length > 0 &&
                                    map(options, (opt, ind)=>{
                                        return <option value={ind} key={ind}> {map(extra[4], (itm)=>{return ('  ' +opt[itm])})}</option>
                                    })
                            }
                        </select>
                        <button  onClick={()=>this.handleChange()} className={"btn btn-dark text-white col-sm-3 border-danger p-0 m-0 mt-1 pt-1"}> Agregar</button>
                    </div>

                    {
                        savedFromDraft[modules][name]

                        &&

                        (savedFromDraft[modules]['paid'] !== savedFromDraft[modules]['total'] )

                        &&

                        sum(map(savedFromDraft[modules][name], (value) => {
                            if (includes(value.label, 'Tarjeta') || includes(value.label, 'tarjeta')) {
                                return value.total
                            }
                        })) >= savedFromDraft[modules]['total']

                        &&

                        sum(map(savedFromDraft[modules][name], (value)=>{
                            if (includes(value.label, 'Tarjeta') || includes(value.label, 'tarjeta')) {
                                return 1
                            }
                        })) > 0

                        &&

                        <button onClick={() => this.handleUpdateSingle()}
                                className={"btn btn-dark text-white col-sm-3 border-danger p-0 m-0 mt-1 pt-1"}> Actualizar </button>

                    }


                    {//showing only if there is a payment method
                        savedFromDraft[modules][name] ?
                            <div className="row col-12 p-0 m-0 mt-5 justify-content-center align-content-center">
                            {map(values, (value, index)=>{
                                return (
                                    <div key={index} className="row col-sm-12 col-lg-10 justify-content-space align-content-sm-between p-0 m-0 mt-4">
                                        <div className="col-4 row text-white fs-6 justify-content-center align-content-center p-0 m-0 ">
                                            {map(extra[4], (itm)=>{
                                                if (itm=== 'label'){
                                                    return value[itm].substring(0,25)
                                                } else {
                                                    return ('  ' +value[itm])
                                                        }
                                                    }
                                                )
                                            }
                                        </div>
                                        <div className="col-6 row justify-content-center align-items-center p-0 m-0 ">
                                            {
                                                ( (includes(value.label, 'Tarjeta') || includes(value.label, 'tarjeta')) ?
                                                <input
                                                    style={value.total ? {border:'2px solid darkgray'} : {border:'2px solid red'}}
                                                    className="row col-6 btn-sm btn"
                                                    type="number"
                                                    value={value.total ? value.total : ''}
                                                    onChange={(e)=>this.handleTotal(e, index)}
                                                /> : <div/>
                                                )
                                            }
                                        </div>
                                        <div className="col-2 row justify-content-center align-items-center p-0 m-0">
                                            <div className="row col-6 justify-content-center align-items-center p-0 m-0 ">
                                                <div className=" row col-6 justify-content-center align-items-center" onClick={() => this.handleDelete(index)}>
                                                    <i className="row col fw-bold p-0 m-5 bi bi-x-circle" style={{color: 'red'}}/>
                                                </div>
                                             </div>
                                        </div>
                                    </div>
                                )
                            }
                            )
                            }
                        </div>
                    :<div/>


                    }


                </div>
            );

        }

    }
}
export default connect(
    (state) => ({
        table: state.UMODULE,
        draft: state.SAVE_DRAFT,
        savedFromDraft: state.SAVE_DRAFT.payload,
        token: state.SESSION.session.token,
    }),
    (dispatch) => ({
        saveDraft: (payload)=> dispatch(saveDraftRequest(payload))})
)(withRouter(PaymentChoose));
