class Combo extends Component{
    constructor(props) {
        super(props);
        this.state = {
            value: [],
            fetch: [],
            page: 0,
            pagination: 10
        }
    }

    async componentDidMount() {
        const {searchVector, endpoint, body, token} = this.props;
        console.log(this.props);
        const apiCall = await getFromApi(endpoint,
            {[searchVector]: body}, token)
            .then(
            (itm) => {
                return (itm.message)
            },
            () => {
                return {label: "No encontrado", value: 'default'}
            })

        if (apiCall.message.length === 0) {
            this.setState((prevState) => {
                return {value: [...prevState.value, 'Error']}
            })
        } else {
            this.setState(() => {
                return {value: apiCall.message}
            })
        }
    }

    render()

    {
        const {showParams} = this.props;
        const value = this.state.value;
        return (

            this.state.value.length > 0 ?
                <div className={"row col justify-content-center align-content-center"}>
                    {map(value, (itm)=>{
                        return <div>
                            {
                                map(showParams, (param)=>{
                                    return itm[param]+' - '
                                })
                            }
                        </div>


                    })}
                </div> : <div>Cargando</div>
        )

    }
}

const DeleteComponent = (props)=>{
    const {cos, token, type, modules, label, savedFromDraft} = props;
    const {component, objective} = cos
    switch (objective[0]) {
        case 'number': return <DeleteDefaultComponent value={component} label={label}/>;
        case 'text': return <DeleteDefaultComponent value={component.length > 0 ? component : 'Vacio' } label={label}/>;
        case 'checkbox': return <DeleteDefaultComponent value={component ? 'Verdadero' : 'Falso' } label={label}/>;
        case 'mdEditor': return <DeleteDefaultComponent value={component.length > 0 ? component : 'Vacio' } label={label}/>;
        case 'cashInPreview': return <SelectMultipleCustomDelete cos={cos} token={ token} type={type} modules={modules}/>;
        case 'selectMultipleSimple': return <SelectSimpleMultipleDelete cos={cos} type={type} modules={modules} savedFromDraft={savedFromDraft}   />;
        case 'selectSimple': return <Combo
            endpoint={process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY+''+objective[3] }
            body={component}
            token={ token}
            searchVector={objective[7]}
            showParams={objective[4]}
        />;
        case 'selectPerson': return <DeleteDefaultComponent value={component } label={label}/>;
        case 'select': return <DeleteDefaultComponent value={component.length > 0 ? component : 'Vacio' } label={label}/>;
        case 'percentage':return <DeleteDefaultComponent value={component.length > 0 ? component : 'Vacio' } label={label}/>;
        case 'rolePicker':return <DeleteDefaultComponent value={component.length > 0 ? component : 'Vacio' } label={label}/>;
        default: return <DeleteDefaultComponent value={component.length > 0 ? component : 'Vacio' } label={label}/>
    }
}


const DeleteComponentSelector = (props)=>{
    const {listComponent, token, modules, savedFromDraft} = props;

    return (
        <div className="row col-sm-12 col-lg-10 justify-content-center align-items-center p-0 m-0">
            {map(listComponent, (cos, key)=>{
                const { objective} = cos
                const type = objective[1]
                return (
                    <div key={key} className="row col-12 justify-content-center align-items-center p-0 m-0">
                            <DeleteComponent cos={cos} token={ token} type={type} modules={modules} label={ objective[2]}  savedFromDraft={ savedFromDraft}/>
                    </div>
                )
            })}
        </div>
    )
}

function findTypeBasedId(component, compList){
    for(const vector in compList){
        if(compList[vector][1] === component){
            return compList[vector]
        }
    }




}
function createDeleteForm(compList, values){
    let dicc = {}
    for (const name in values) {
        const component = values[name]
        const objective = findTypeBasedId(name, compList)
        const formDelete = {
            objective, component
        }
        if( objective ) {
            if (dicc.length > 0 ) {
                dicc = [...dicc, formDelete]
            } else {
                dicc = [formDelete]
            }
        }

    }
        return dicc
    }
class DeleteEntry extends Component {
    constructor(props) {
        super(props)
    }
    deleteButton(){
        const {sending, error} = this.props.cud;
        let payload = {
            modules: this.props.modules,
            mode: 'delete'
        }
        if(!(error && sending)){
            this.props.postToApi(payload)
        }
    }

    render() {
        const {values, compList} = this.props
        const deleteForm = createDeleteForm(compList, values)
        return (
                <div className="row col-sm-12 col-lg-10 justify-content-center align-items-center p-0 m-0">
                    <div className="row col-12 justify-content-center align-items-center p-0 m-0">
                             <div className="row col-12 justify-content-center align-items-center p-0 m-0 fs-6">
                                <DeleteComponentSelector listComponent={deleteForm} token={this.props.token} modules={this.props.modules} savedFromDraft={{[this.props.modules]:values}} />
                            </div>

                    </div>
                    <div className="row col-12 mt-5 justify-content-center align-items-center p-0 m-0">
                            <div className="row col-sm-4 col-lg-6 justify-content-center align-items-center p-0 m-0">
                                <button className="col row p-0 m-0 btn btn-sm btn-danger" onClick={()=>this.deleteButton()}>Borrar</button>
                            </div>
                    </div>
                </div>

        );
    }
}

export default connect(
    state => ({
        session: state.SESSION.session,
        table: state.UMODULE,
        cud: state.UMODULECUD

    }),
    dispatch => ({
        saveDraft: (payload)=> dispatch(saveDraftRequest(payload)),
        postToApi: (payload)=> dispatch( uModuleRequestCud(payload))
    }))(withRouter(DeleteEntry))
