import React, { Component } from 'react';
import { connect } from 'react-redux';
import { uModuleRequest } from "../../../store/actions/uModule";
import { withRouter } from "react-router-dom";




class PaginationComponent extends Component {
    constructor(props) {
        super(props);
    this.state = {
        currentPageInput: parseInt(this.props.table.payload[this.props.modules].last.page),
    };
}


    handleInputChange = (op) => {

        this.setState(prevState =>{
            const value = op === 'add' ? prevState.currentPageInput + 1 : prevState.currentPageInput > 0 ? prevState.currentPageInput - 1 : 0;
            return { currentPageInput: value }
        });
    };

    handlePageChange = () => {
        const {table, modules} = this.props;
        const newPage = parseInt(this.state.currentPageInput, 10);
        if (!isNaN(newPage)) {
            const payload = {
                modules: this.props.modules,
                body: { skip: newPage, compList:this.props.form},
                values: table.payload[modules].last.values, mode:'read' , page: newPage}
            this.props.readTableInformation(payload)
        }
    };

    render() {
        const { modules, table } = this.props;
        const currentPage = table.payload[modules].last.body.skip;
        const {currentPageInput} = this.state;
        return (
                <div className="row col-12 min-vw-100  p-0 m-0 justify-content-center align-content-center">
                    <div className="row col-sm-12 col-lg-6 m-0 p-0  justify-content-center">
                        <div className="row col-4 justify-content-center align-content-center ">
                            <div className="row col-5 btn btn-outline-danger fw-bolder justify-content-center align-content-center"  onClick={() => this.handleInputChange('rest')}>- </div>
                        </div>

                        <div className="row col-4 justify-content-center align-content-center">
                            <button className="row col-5 btn btn-danger  btn btn-danger fw-bolder col " onClick={() => this.handlePageChange()}>
                                Ir
                            </button>
                        </div>

                        <div className="row col-4 justify-content-center align-content-center">
                            <div className="row col-5 btn btn-outline-danger fw-bolder" onClick={() => this.handleInputChange('add')}>+</div>
                        </div>

                    </div>




                    <div className="row col-12 justify-content-center align-content-center m-0 p-0 mt-4">
                        <div className="row col-sm-12 col-lg-6 fs-3 justify-content-around align-content-center">
                            <div className="row col-3 justify-content-center align-items-center">
                                <div className="row col-sm-5 col-lg-6 btn btn-outline-black col-sm-5 col-lg-1 ">{currentPage}</div>
                            </div>

                            <div className="row col-3 justify-content-center align-items-center">
                                <div className="row col-sm-3 col-lg-6 btn btn-outline-danger col-sm-5 col-lg-1 ">{currentPageInput}</div>
                            </div>

                        </div>
                    </div>

                </div>
        );
    }
}

export default connect(
    (state) => ({
        table: state.UMODULE,
        token: state.SESSION.session.token,
    }),
    (dispatch) => ({
        readTableInformation: (payload) => dispatch(uModuleRequest(payload)),
    })
)(withRouter(PaginationComponent));
