import React, {Component} from "react";
import {includes} from "lodash";
import MdEditor from "../Components/MdEditor";
import Select from "../Components/Select";
import RolePicker from "../Components/RolePicker";
import SelectSimple from "../Components/SelectSimple";
import CashInFront from "./CashInFront";
import PersonSearch from "../Components/PersonSearch";
import {connect} from "react-redux";
import {saveDraftRequest} from "../../../store/actions/common";
import {withRouter} from "react-router-dom";
import Loading from "../Loading";
import Checkbox from "../Components/Checkbox";
import PaymentChoose from "../Components/PaymentChoose";
import Text from "../Components/Text";
import Percentage from "./Percentage";



class ComponentCustom extends Component{
    constructor(props) {
        const utilizeFocus = () => {
            const ref = React.createRef()
            const setFocus = () => {ref.current &&  ref.current.focus()}

            return {setFocus, ref}
        }
        super(props);

        this.inputFocus = utilizeFocus()
        const { modules, savedFromDraft } = this.props;
        this.state={
            options: {},
            values: savedFromDraft[modules]
        }
    }

    handle(e){
        const { modules, savedFromDraft, saveDraft } = this.props;
        const { name, value } = e.target;
        // Create a new copy of the dictionary with the updated value
        const newDictionary = {
            ...savedFromDraft[modules],
            [name]: value,
        }
        const payload = {
            values: newDictionary,
            modules: modules
        }
        saveDraft(payload)

    }

    handleArray(e){
        e.target.value = includes(e.target.value, ',') ? e.target.value.split(',') : e.target.value.split(' ')
        this.props.handle(e)
    }
    render(){
        const { savedFromDraft, modules, type, name, ref, invalid, extra, getter, token, onChangeValue,  values} = this.props;
        if(!(savedFromDraft[modules])){
            return (
                <Loading label={extra[3]}/>
            )
        }
        let style = {
        }
        for(const item in invalid){
            if(invalid[item].name === name){
                style.border = '3px solid red'
                style.borderRadius = '5px'
            }
        }
        const value = values[name]
        switch(type){
            case 'label': {return <div className={'col row justify-content-center align-content-center fs-3 text-danger '}>{extra[3]}</div> }

            case 'mdEditor': {return <MdEditor value={value ? value : ''} onChangeValue={ onChangeValue} name={this.props.name}/>}

            case 'select': {
                return <Select type={type} value={value} name={name} onChangeValue={onChangeValue} extra={extra} />
            }
            case 'percentage': {
                return (
                    <Percentage value={value} name={name} onChangeValue={onChangeValue}/>

                )
            }
            case 'array': {
                return <input className="col-12" type={type} value={value} name={name} onChange={e=>this.handleArray(e)}/>
            }
            case 'rolePicker': {
                return <RolePicker extra={extra} type={type} value={value} name={this.props.name} onChangeValue={onChangeValue} />
            }

            case 'selectSimple': {
                return <SelectSimple
                    valueOption={extra[7]}
                    type={type}
                    value={value}
                    name={name}
                    onChangeValue={onChangeValue}
                    extra={extra}
                    token={token}
                    getter={getter}/>

            }

            case 'selectPerson': {
                return <PersonSearch
                    valueOption={this.props.extra[7]}
                    type={this.props.type} value={value}
                    name={this.props.name}
                    modules={this.props.modules}
                    extra={this.props.extra}
                    token={this.props.token}
                    getter={this.props.getter}
                    onChangeValue={onChangeValue}
                />
            }
            case 'selectMultipleSimple': {
                return <PaymentChoose
                    type={type}
                    name={name}
                    extra={extra}
                    token={token}
                    modules={modules}
                    onChangeValue={onChangeValue}/>
            }
            case 'cashInPreview': {
                return <CashInFront
                    type={this.props.type}
                    value={value}
                    name={this.props.name}
                    modules={this.props.modules}
                    extra={this.props.extra}
                    token={this.props.token}
                    getter={(name)=>{return values[name]}}
                    onChangeValue={onChangeValue}
                    style={style}
                />
            }

            case 'checkbox': {

                return <div className="row justify-content-center bg-dark">
                    <Checkbox
                        type={type}
                        name={name}
                        modules={modules}
                        onChangeValue={ onChangeValue}
                    />
                </div>
            }
            default: {
                return(<div className="row">
                    <Text  style={style} ref={ref} type={type} value={value} name={name}  modules={modules} onChangeValue={ onChangeValue }/>
                </div>)
            }


        }
    }
}
export default connect(
    state => ({
        session: state.SESSION.session,
        draft: state.SAVE_DRAFT,
        savedFromDraft: state.SAVE_DRAFT.payload

    }),
    dispatch => ({
        saveDraft: (payload)=> dispatch(saveDraftRequest(payload))}))(withRouter(ComponentCustom))

