

import {put, select} from 'redux-saga/effects';

export default function* saveDraft({payload}) {
    try {
        let dictionary = {}
        const draft = yield select(state => state.SAVE_DRAFT);
        const {values, modules} = payload
            dictionary = {...draft.payload}
            if(!( dictionary[modules])){
                dictionary[modules] = {}
            }
            for (const i in values){
                dictionary[modules][i] = values[i]
            }
            yield put({type: "SAVE_DRAFT_SUCCESS", payload:{...dictionary}})
        } catch (err) {
        yield put({type: "SAVE_DRAFT_FAILED"});
    }
}




