import React, {Component} from 'react';
import {connect} from "react-redux";
import {withRouter} from "react-router-dom";
import AddNew from "../FormCreator/AddNew";

class UModuleHandler extends Component {
    render() {
        const {modules, valuesUpdate, mode, handlePageModules, form,validate} = this.props;
        return (
            <div className={'row '}>
                {(<AddNew
                             modules={modules}
                             valuesUpdate={valuesUpdate}
                             mode={mode}
                             handlePageModules={handlePageModules}
                             form={form}
                             validate={validate}/>)}
            </div>
        );
    }
}

export default connect(
    (state) => ({
        cud: state.UMODULECUD,

    }),
    () => ({})
)(withRouter(UModuleHandler));

