import { put, select, call} from 'redux-saga/effects';
import Http from '../services/http'
import {uModuleFailedCud, } from "../actions/uModule";

export default function* uModuleRequestedCUD({payload}) {

    try {

        const session = yield select(state => state.SESSION.session);
        const draft = yield select(state => state.SAVE_DRAFT);
        const cudState = yield select(state => state.UMODULECUD)
        const body = draft.payload[payload.modules]
        const cud = payload.mode === 'delete' ? '/delete/' : (body._id ? '/update' : '/create/')
        const endpointToPost = process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY + payload.modules + cud
        if(cudState.sending){
            const tableInformation = yield call(Http.post, endpointToPost , body, session.token)
            if (!(tableInformation.isError) ) {
                yield put({type: 'UMODULE_SUCCESS_CUD', payload:{[payload.modules]: tableInformation}})
            } else {
                    yield put(uModuleFailedCud(tableInformation.message));
            }
        }

    }
    catch (e) {
        yield put(uModuleFailedCud('Error Con el Servidor'));
    }
}
