const permissions = (permission) =>{
    if(permission.includes('admin')){
        return 1
    }
    if (permission.includes('cajero') && permission.includes('vendedor')){
        return 2
    }
    if(permission.includes('cajero') && !permission.includes('vendedor')){
        return 3
    }
    if(permission.includes('vendedor') && !permission.includes('cajero')){
        return 4
    }
    else {
        return 0
    }

}
export {permissions}
