import React, {Component} from 'react';
import {connect} from "react-redux";
import {withRouter} from "react-router-dom";
import Loading from "../../common/Loading";
import {Error404} from "../../common";
import AdminHome from "./AdminHome";
import {serverRequest} from "../../../store/actions/common";
import {permissions} from "../../../store/services/roles";
import  CajeroHome from "./CajeroHome";
import VendedorHome from "./VendedorHome";
class Home extends Component {
    constructor(props) {
        super(props);

    }

    componentDidMount() {
        this.props.request({
            type: 'Tienda Taller',
            confirmed: true,
            accepted: true,
            from: new Date().setHours(0, 0, 0, 0),
            to: new Date().setHours(23, 59, 59, 999)
        })
    }
    render() {

        if (this.props.home.sending) {
            return (
                <Loading label={'Cargando'}/>
            )
        }

        if (this.props.home.error) {
            return (
                <Error404/>
            )
        }
        const role = this.props.session.profile.role
        if (this.props.home.success) {
            switch (permissions(role)){
                case 1:{ return <AdminHome/>}
                case 2:{ return <CajeroHome/>}
                case 3: {return <CajeroHome/>}
                case 4: {return <VendedorHome/>}
            }
        }
    }
}

export default connect(
    state => ({
        session: state.SESSION.session,
        home: state.HOME
    }),
    dispatch =>({
        request: (payload)=> dispatch(serverRequest(payload))}
))(withRouter(Home))

