import React, {Component} from 'react';
import {connect} from "react-redux";
import {withRouter} from "react-router-dom";
import Sections from "./sections";
import {uModuleRequest} from "../../../store/actions/uModule";
import {Error404} from "../index";
import Loading from "../Loading";
import TableHandler from "./tableHandler";
import UModuleHandler from "./uModuleHandler";

class ModuleHandler extends Component {
    constructor(props) {
        super(props);
        this.state = {
            page: '0',
            skip: 0,
            limit: 0,
            valuesUpdate: {},
            mounted: false
        }
    }



    handlePage(index,mode, values, skip){
        this.setState(
            (prevState)=>{
                const payload = {modules: this.props.modules, body: { skip: skip, compList:this.props.form}, values: values, mode:mode ,page: index}
                this.props.readTableInformation(payload)
                return ({page: index,mode: mode,  valuesUpdate: values, skip: skip, compList:prevState.form})
            })
    }
    render() {
        const {table, modules} = this.props;
        const {success, error, payload, sending} = table
        if (error) {
            return (
                <div>
                    <div className={"row col justify-content-start align-content-start p-0 m-0"}>
                        <Sections
                            compList={this.props.form}
                            modules={modules}
                            pagehandler={(index, mode, values, skip) => this.handlePage(index, mode, values, skip)}/>
                    </div>
                    <Error404 label={'Error'}/>

                </div>
            )
        }
        if (sending) {
            return (
                <div>
                    <div className={"row col justify-content-start align-content-start p-0 m-0"}>
                        <Sections compList={this.props.form}
                                  modules={modules} pagehandler={(index, mode, values, skip) => this.handlePage(index, mode, values, skip)}/>
                    </div>
                    <Loading label={'Cargando'}/>
                </div>

            )
        }
        if (success && payload) {
            if (payload[modules]) {
                switch (payload[modules].last.page) {
                    case '1': {
                        return (
                            <div className={"row col justify-content-start align-content-start p-0 m-0"}>
                                <Sections compList={this.props.form} modules={modules} pagehandler={(index, mode, values, skip) => this.handlePage(index, mode, values, skip)}/>
                                <UModuleHandler
                                    modules={modules}
                                    valuesUpdate={this.state.valuesUpdate ? this.state.valuesUpdate : {}}
                                    mode={payload[this.props.modules].last.mode}
                                    handlePageModules={(index, mode, values, skip) => this.handlePage(index, mode, values, skip)}
                                    form={this.props.form}
                                    validate={this.props.validate}
                                />
                            </div>
                        )
                    }

                    default: {
                        return (
                            <div className={"row col-12 justify-content-start align-content-start p-0 m-0"}>
                                <Sections
                                    compList={this.props.form}
                                    modules={modules}
                                    pagehandler={(index, mode, values, skip) => this.handlePage(index, mode, values, skip)}
                                    role={this.props.role}
                                />
                                <TableHandler
                                    prevState={this.state.valuesUpdate}
                                    handlePageCallback={(values) => this.handlePage('0', 'read', values, '0')}
                                    header={this.props.header}
                                    onUpdateValues={(values) => this.handlePage('1', 'update', values, '0')}
                                    onDeleteValues={(values) => this.handlePage('1', 'delete', values, '0')}
                                    modules={modules}
                                    form={this.props.form}
                                />
                            </div>


                        )
                    }
                }
            }
        }
    }
}

export default connect(
    (state) => ({
        table: state.UMODULE,
        role: state.SESSION.session.profile.role

    }),
    dispatch => ({
        readTableInformation:(payload)=> dispatch(uModuleRequest(payload))
    })
)(withRouter(ModuleHandler));
