
import React, {Component} from "react";
import {map} from "lodash";
import {getFromApi} from "../../../../store/services/getFromApiSimple";



class Combo extends Component{
    constructor(props) {
        super(props);
        this.state = {
            value: [],
            fetch: [],
            page: 0,
            pagination: 10
        }
    }

    async componentDidMount() {
        const {searchVector, endpoint, body, token} = this.props;
        const apiCall = await getFromApi(endpoint, {[searchVector]: body}, token).then(
            (itm) => {
                return (itm.message)
            },
            () => {
                return {label: "No encontrado", value: 'default'}
            })

        if (apiCall.message.length === 0) {
            this.setState((prevState) => {
                return {value: [...prevState.value, 'Error']}
            })
        } else {
            this.setState(() => {
                return {value: apiCall.message}
            })
        }
    }

    render() {
        const {showParams} = this.props;
        const value = this.state.value;
        return (
            this.state.value.length > 0 ?
                <div className={"col-12 p-0 m-0 row "}>
                    {map(value, (itm)=>{
                        return<div>
                            {map(showParams, (param)=>{return itm[param]+' - '})}
                        </div>
                    })}
                </div> : <div>Cargando</div>
        )

    }
}

class MultipleListViewer extends Component{
    constructor(props) {
        super(props);
        this.state = {
            showing: false
        }
    }
    handleShowing(e){
        e.preventDefault();
        this.setState((prevState)=>{
            return {
                showing: !prevState.showing
            }
        })
    }
    render(){
        const {itemFromApi, itemFromTheForm, formComponent, token} = this.props
        return (
            this.state.showing ?
                <div className="row modalMdEditorView">
                        <div className=" col-12 justify-content-end align-items-start ">
                            <div className="row col justify-content-end align-items-start">
                                <i className="bi bi-x text-white"
                                   onClick={(e) => this.handleShowing(e)}>
                                </i>
                            </div>
                        </div>
                    <div className="col-12 justify-content-center align-items-center m-0 p-0 ">
                        <Combo
                            endpoint={process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY + '' + formComponent[3]}
                            body={itemFromApi[itemFromTheForm[0]]}
                            token={token}
                            searchVector={formComponent[7]}
                            showParams={formComponent[4]}
                        />
                    </div>
                </div>
                :
                <div className=" btn-sm text-info pt-0 pb-0"
                     onClick={(e) => this.handleShowing(e)}>
                    <i className="bi bi-chat-dots"></i>
                </div>
        )
    }
}




export default MultipleListViewer;
