import React, {Component} from 'react';
import {connect} from "react-redux";
import {serverRequest} from "../../../store/actions/common";
import {withRouter} from "react-router-dom";
import {map} from "lodash";

import Chartx from "./Chart";
import {buttonsForRole} from "./buttons";
import {permissions} from "../../../store/services/roles";
import BarChart from "./Component/BarChart";


const getAtFlightValues = (range) =>{
    let total = 0; // Total
    let totalPorTarjeta = {} // obj with all cards totals
    // --- Promo dictionaries
    let promotionsDictionary = {}

    for (const sell in range){
        const actualSell = range[sell] // La venta en si
        const isConfirmedAndAccepted = actualSell.accepted && actualSell.confirmed
        if (isConfirmedAndAccepted){
            total = total +  parseInt(actualSell.total, 10)
            for(const promo in actualSell.promotion){
                const promoId = actualSell.promotion[promo]._id // guardo el ID
                if (promotionsDictionary[promoId] && promotionsDictionary[promoId].cell === promoId){

                    promotionsDictionary[promoId].value = promotionsDictionary[promoId].value +  parseInt(actualSell.promotion[promo].total, 10)
                    promotionsDictionary[promoId].cell = promotionsDictionary[promoId].cell + ' ' +actualSell._id
                }
                else {
                    promotionsDictionary[promoId] =
                        {
                            value: parseInt( actualSell.promotion[promo].total , 10 ),
                            label: actualSell.promotion[promo].label ,// "label": "Tarjeta Debito"
                            type: actualSell.promotion[promo].type,
                            cell: actualSell._id
                        }

                }


            }

        }

    }
    totalPorTarjeta = promotionsDictionary
    return {
        total,
        totalPorTarjeta,
    }


}


export class CajeroHome extends Component {
    constructor(props) {
        super(props);
        this.state = {
            sections: {
                chart: false,
                search: false,
                detail: false,
                buttons: false,
                dayMessage:false
            }
        }
    }
    handleFilter(data){
        this.props.request(data)
    }

    handleSection(section) {
        this.setState((prevState) => {
            return {sections: {[section]: !prevState.sections[section]}}
        })
    }


    cleanHandler() {
        this.setState({
            type: undefined,
            confirmed: undefined,
            accepted: undefined,
            from: undefined,
            to: undefined,
            otd: undefined,
            message: undefined
        })
        this.props.request({})
    }

    inputHandler(e) {
        this.setState({[e.target.name]: e.target.value})
    }

    stateHandler(name, value) {
        this.setState({[name]: value})
    }

    checkBoxHandler(e) {
        this.setState((prevState) => {
            return {
                [e.target.name]: prevState[e.target.name] ? !prevState[e.target.name] : true
            }

        })
    }

    buttonHandler(e) {
        e.preventDefault(e)
        this.props.request({
            type: this.state.type,
            from: this.state.from,
            to: this.state.to,
            confirmed: this.state.confirmed ? 1 : 0,
            accepted: this.state.accepted ? 1 : 0,
            ticketNum: this.state.otd,
            message: this.state.message
        })
    }




    render() {
        const from = this.props.home.request.message.rangeRequest.from
        const targetDate = this.props.home.request.message.rangeRequest.to
        const box = getAtFlightValues(this.props.home.request.message.csv)
        return (
            <div className={'container-fluid bg-black '}>
                <div className="row col min-vh-100">
                    <div className="row col justify-content-center align-content-start">
                        <div className="row col-12 justify-content-center bg-black text-white fw-bold fs-2 m-3 mt-3 swing-in-top-fwd">
                            <div className="row col-6 justify-content-center">
                                {this.props.home.request.message.dayMessage}
                            </div>
                        </div>
                        <div className="row col-sm-12 col-lg-8 viewArea ">
                            <div className="row">
                                <div className="col justify-content-start align-content-center ">
                                    <div className="row fs-1 text-white fw-bold">
                                        Ver Modos de Pago
                                    </div>
                                </div>
                                <button className="col-1 btn btn-sm" onClick={() => this.handleSection('box')}>
                                    {
                                        this.state.sections.box ?
                                            <i className="col row bi bi-caret-down-fill fs-1 fw-bold text-white justify-content-center align-content-center"/>
                                            :
                                            <i className="col row bi bi-caret-left-fill fs-1 fw-bold text-white justify-content-center align-content-center"/>
                                    }
                                </button>
                            </div>
                        </div>
                        <div className="row col-sm-12 col-lg-8 swing-in-top-fwd viewPart ">
                            <div className="row col-12 swing-in-top-fwd justify-content-center">
                                <div className="row col-12 justify-content-center align-content-center ">
                                    {map(buttonsForRole(permissions(this.props.session.profile.role)), (button, key) => {
                                        return (<div key={key} className=" row col  m-1">
                                            <button onClick={() => this.handleFilter(button)}
                                                    className={"btn btn-sm fw-bold  btn-danger bg-black"}>
                                                {button.label}
                                            </button>
                                        </div>)
                                    })}
                                </div>

                            </div>

                            {this.props.home.request.message.csv.length > 0 ?
                                <div className="row col justify-content-center align-content-center">
                                    <div className="col-sm-10 col-lg-6 justify-content-center align-content-center  row ">
                                        <div className="row col-12 justify-content-center">
                                            <div className="row col-6 fs-2 justify-content-center bold">
                                                {from.split('T')[0]}
                                            </div>
                                        </div>
                                        <div
                                            className="row mt-1 justify-content-center align-content-center text-white fw-bold">
                                            Ventas por
                                            Vendedor: {this.props.home.request.message.csv.length} Ventas!
                                        </div>
                                        <div
                                            className="row col-sm-12 col-lg-12 justify-content-center align-content-center bg-black">
                                            <Chartx
                                                id={'chart-bar-vendedores'}
                                                className={'chart-canvas chartjs-render-monitor'}
                                                type={'pie'}
                                                labels={map(this.props.home.request.message.sellByCreator, (itm) => {
                                                    return (itm.label + ' --' + itm.value + ' $')
                                                })}
                                                data={map(this.props.home.request.message.sellByCreator, (itm) => {
                                                    return (itm.value)
                                                })}
                                            />
                                        </div>
                                    </div>
                                    <div className="col-sm-10 col-lg-12 justify-content-center align-content-center row ">
                                        <div className="row col-12 justify-content-center">
                                            <div className="row col-6 fs-2 justify-content-center bold">
                                                {targetDate.split('T')[0]}
                                            </div>
                                        </div>
                                        <div
                                            className="row mt-1 justify-content-center align-content-center text-white fw-bold">
                                            Ventas por Producto
                                        </div>
                                        <div
                                            className="row col-sm-12 col-lg-8 justify-content-center align-content-center bg-black">
                                            <BarChart data={this.props.home.request.message.sellByProducts ? map(this.props.home.request.message.sellByProducts, (item)=>{return item}) : []}/>

                                        </div>

                                    </div>
                                </div> : <div className={"col-sm-10 col-lg-6 justify-content-center align-content-center row fs-2 fw-bold text-white"}>No se encontro ningun dato!</div>

                            }












                            {this.state.sections['box'] ?
                                <div className="row text-white">
                                    <div
                                        className="col-sm-12 col-lg-12 row justify-content-center align-content-center mt-5">

                                        <div className="col-10 row justify-content-around fs-1">
                                            <div className="col-6">
                                                Total
                                            </div>
                                            <div className="col-6">
                                                {box.total}
                                            </div>
                                        </div>


                                        <div className="col-sm-12 col-lg-10 row justify-content-around fs-2 ">

                                            <div className="col-12 row justify-content-start fs-1">
                                                Modos de Pago
                                            </div>

                                            <div className="row justify-content-center align-content-center ">

                                                {map(box.totalPorTarjeta, (card, key) => {
                                                    return (
                                                        <div key={key}
                                                             className="row col-12 mt-1  btn btn-dark fw-bold ">
                                                            <div className="col-sm-12 col-lg-4 ">
                                                                {card.label}
                                                            </div>
                                                            <div className="col-sm-12 col-lg-3">
                                                                {card.type}
                                                            </div>
                                                            <div className="col-sm-12 col-lg-5">
                                                                {card.value}
                                                            </div>


                                                        </div>

                                                    )
                                                })}

                                            </div>
                                        </div>


                                    </div>
                                </div> : <div className="d-none"/>
                            }
                        </div>
                    </div>
                </div>
            </div>
        );
    }


}

export default connect(
    state => ({
        session: state.SESSION.session,
        home: state.HOME
    }),
    dispatch => ({
            request: (payload) => dispatch(serverRequest(payload))
        }
    ))(withRouter(CajeroHome))
