import React, {Component} from 'react';
import { map} from "lodash";


class Select extends Component {
    constructor(props) {
        super(props);

    }

    onChangeOption(e){
        const { name, extra,onChangeValue} = this.props;
        const {value} = e.target;
        this.setState(()=>{
            onChangeValue({[name]:extra[3][value]})
            return {value: value}
        })


    }
    render() {
        const { value,name, extra} = this.props;
        const valueToOptions = extra[3].indexOf(value)
        return (
           <select value={valueToOptions} name={name}  onChange={(e)=>this.onChangeOption(e)}>
              {map(extra[3], (itm, key)=> {
                   return (<option key={key} value={key}> {itm}</option> )
               })}
           </select>
        );
    }
}

export default Select;
