import React, {Component, Fragment} from 'react'
import {BrowserRouter as Router, Route, Switch, HashRouter} from 'react-router-dom';
import {Login} from '../components/common/index'
import {connect} from "react-redux";
import NavBar from "./navbar";
import ModuleParser from "../components/common/ModuleParser";
import ScreenView from "./ScreenView";
import Home from "../components/Components/Home";
import { map} from 'lodash';


const createRoutes = (hasher) =>{
    return map(hasher, (itm, key)=>{
        return {
            path: itm.path,
            exact: true,
            main: () => <ModuleParser key={key} modules={itm.modules} header={itm.header} form={itm.form} validate={itm.validate}/>
        }
    })

}



class CustomRouter extends Component {
    constructor(props) {
        super(props)
    }

    render() {
        const {routes} = this.props.session;
        const {logged} = this.props.login
        if(logged){
            const routesMenu = routes.routesMenu
            const staticRoutes = [
                {
                    path: '/',
                    exact: true,
                    main: () => <Home/>
                },
                {
                    path: '/service-worker.js',
                    exact: true,
                    main: () => <div></div>
                }
            ]
            const routesHash =[ ...staticRoutes,...createRoutes(routes.routesHash)]
            return (
                <HashRouter>
                    <Switch>
                        <Fragment>
                            <div className='container-fluid row col p-0 m-0 min-vh-100 bg-black align-content-start'>
                                <NavBar routes={routesMenu}/>
                                {routesHash.map((route, index) => (
                                    <Route key={index} path={route.path} exact={route.exact}>
                                        <ScreenView component={<route.main/>}/>
                                    </Route>
                                ))}
                            </div>
                        </Fragment>
                    </Switch>
                </HashRouter>
            )
        } else {
            return (
                <div className={'bg-black min-vh-100'}>
                        <Router>
                        <Switch>
                            <Fragment>
                                <Login/>
                            </Fragment>
                        </Switch>
                    </Router>
                </div>
            )
        }
    }

}



export default connect(
    state => ({
        session: state.SESSION.session,
        login: state.LOGIN
    })
)(CustomRouter)
