import React, {Component} from 'react';
import {connect} from "react-redux";
import {saveDraftRequest} from "../../../store/actions/common";
import {withRouter} from "react-router-dom";



class Text extends Component {
    constructor(props) {
        super(props);
        const {value} = this.props;
        this.state ={
            value: value
        }

    }
    handle(){
        const { name,   onChangeValue } = this.props;
        const value = this.state.value
        this.setState((prevState)=>{
            onChangeValue({[name]:value})
            return {focus: !prevState.focus}
        })


    }
    handleChange(e){
        const {type, name,   onChangeValue} = this.props
        this.setState(()=>{
            const value = type === 'number' ? parseInt(e.target.value, 10) : e.target.value
            onChangeValue({[name]:value})
            return {value: value}
        })
    }
    leFocus(){
        this.setState({focus:true, value: this.props.savedFromDraft[this.props.modules][this.props.name] })
    }

    render() {
        const { name, type, ref, style,modules,  savedFromDraft } = this.props;
        const value = this.state.focus && this.state.value ? this.state.value : savedFromDraft[modules][name]
        return (
            <div className="row">
                <input
                    style={style}
                    ref={ref}
                    type={type}
                    value={value}
                    name={name}
                    onFocus={(e)=>this.leFocus(e)}
                    onChange={e => this.handleChange(e)}
                    onBlur={e => this.handle(e)}/>
            </div>
        );
    }
}


export default connect(
    (state) => ({
        table: state.UMODULE,
        draft: state.SAVE_DRAFT,
        savedFromDraft: state.SAVE_DRAFT.payload,
        token: state.SESSION.session.token,
    }),
    (dispatch) => ({
        saveDraft: (payload)=> dispatch(saveDraftRequest(payload))})
)(withRouter(Text));
